pages = data['pages']

def enrich_contenu(content, new_blocks):
    marker = '<section class="content-section" id="quiz">'
    idx = content.find(marker)
    if idx == -1:
        idx = content.rfind('</section>')
    return content[:idx] + new_blocks + content[idx:]

# ===== theorie-communication/communication-interpersonnelle =====
k = 'theorie-communication/communication-interpersonnelle'
extra = (
    '<h3>Analyse transactionnelle et positions de vie</h3>'
    '<p class="resume-text">L\'<strong>analyse transactionnelle</strong> (Eric Berne, <em>Des jeux et des hommes</em>, 1964) propose un modele de la communication interpersonnelle fonde sur trois etats du moi : le Parent (normes, valeurs, comportements introjetes des figures parentales), l\'Adulte (traitement rationnel de l\'information, ici et maintenant) et l\'Enfant (sentiments, besoins, comportements spontanes ou adaptes de l\'enfance). Toute communication est une transaction entre ces etats. Une transaction complementaire (Parent-Enfant, Adulte-Adulte) permet la communication fluide ; une transaction croisee cree un conflit.</p>'
    '<p class="resume-text">Thomas Harris popularisa le concept de <strong>positions de vie</strong> : Je suis OK/Tu es OK (position saine, ouverture a l\'autre), Je suis OK/Tu n\'es pas OK (arrogance, condescendance), Je ne suis pas OK/Tu es OK (soumission, complexe d\'inferiorite), Je ne suis pas OK/Tu n\'es pas OK (desespoir, nihilisme). Ces positions colorent inconsciemment toutes nos interactions. L\'objectif therapeutique est d\'atteindre la position OK-OK, base d\'une communication authentique et respectueuse.</p>'
    '<div class="highlight-box"><p>L\'analyse transactionnelle d\'Eric Berne : nous jouons des jeux psychologiques dans nos interactions quotidiennes. En prendre conscience est le premier pas vers une communication plus authentique.</p></div>'
    '<h3>Negociation et gestion des conflits</h3>'
    '<p class="resume-text">La <strong>Communication Non Violente</strong> (CNV), developpee par Marshall Rosenberg (<em>Les mots sont des fenetres ou des murs</em>, 1999), propose un processus en quatre etapes pour transformer les conflits en connexion : Observer sans evaluer (decrire les faits sans jugement), Exprimer ses Sentiments (en prenant responsabilite de ses emotions), Identifier ses Besoins (les besoins universels sous-jacents aux emotions) et formuler une Demande concrete, realiste et ouverte. La CNV distingue les demandes (ouvertes au refus) des exigences (imposees).</p>'
    '<p class="resume-text">La <strong>methode Harvard</strong> de negociation (Roger Fisher, William Ury, <em>Getting to Yes</em>, 1981) distingue les positions (ce que les parties disent vouloir) des interets (pourquoi elles le veulent). Une negociation efficace cherche les interets sous les positions, invente des options de gain mutuel et s\'appuie sur des criteres objectifs. Cette approche, utilisee en diplomatie internationale, en mediation familiale et en negociation commerciale, a revolutionne la pratique de la resolution de conflits.</p>'
    '<div class="highlight-box"><p>La CNV de Rosenberg : derriere toute critique ou exigence se cache un besoin non exprime. Identifier ce besoin transforme le conflit en dialogue.</p></div>'
    '<h3>Communication interculturelle et chocs culturels</h3>'
    '<p class="resume-text">La <strong>communication interculturelle</strong> etudie comment les differences culturelles affectent les interactions. Geert Hofstede a identifie six dimensions culturelles qui varient selon les pays : la distance hierarchique (acceptation des inegalites de pouvoir), l\'individualisme vs collectivisme, la masculinite vs feminite, l\'aversion a l\'incertitude, l\'orientation a long terme vs court terme, et l\'indulgence vs la retenue. Ces dimensions expliquent de nombreux malentendus dans les equipes internationales et les negociations commerciales transculturelles.</p>'
    '<p class="resume-text">Le <strong>choc culturel</strong> (Kalervo Oberg, 1960) designe le stress et la desorientation ressentis lors d\'une immersion dans une nouvelle culture. Il se deroule en quatre phases : lune de miel (enthousiasme), frustration (choc), adaptation (ajustement progressif) et integration (aisance biculturelle). Comprendre ce processus est essentiel pour les expatries, les migrants, les travailleurs humanitaires et les etudiants en mobilite internationale. La competence interculturelle — capacite a communiquer efficacement a travers les differences — est aujourd\'hui une competence professionnelle majeure.</p>'
    '<div class="highlight-box"><p>Hofstede : la dimension individualisme/collectivisme est l\'une des plus decisives en communication internationale. Un Americain et un Japonais peuvent parler la meme langue et se comprendre tres mal.</p></div>'
)
pages[k]['content'] = enrich_contenu(pages[k]['content'], extra)
print(f"{k}: {len(pages[k]['content'])} chars")

# ===== theorie-communication/rhetorique-et-persuasion =====
k = 'theorie-communication/rhetorique-et-persuasion'
extra = (
    '<h3>La rhetorique moderne et les figures de style</h3>'
    '<p class="resume-text">La <strong>Nouvelle Rhetorique</strong> de Chaim Perelman et Lucie Olbrechts-Tyteca (<em>Traite de l\'argumentation</em>, 1958) restaura la rhetorique comme discipline academique apres des siecles de discredit. Perelman distingua la demonstration (logique formelle, valide par sa forme) de l\'argumentation (cherchant a obtenir l\'adhesion d\'un auditoire particulier). Il identifia trois types d\'arguments : les arguments quasi-logiques (analogies, paradoxes), les arguments fondes sur la structure du reel (lien de causalite, argument pragmatique) et les arguments qui fondent cette structure (exemple, illustration, modele).</p>'
    '<p class="resume-text">Les <strong>figures de style</strong> ne sont pas des ornements decoratifs mais des strategies argumentatives. La metaphore structure la comprehension : parler d\'un debat comme d\'une guerre (<em>vos arguments sont indefendables</em>, <em>il a attaque mes positions</em>) impose une frame cognitive combative. L\'anaphore (repetition en debut de phrase) cree un effet de matraquage emotionnel. La litote dit moins pour signifier plus. L\'ironie cree une connivence avec l\'auditoire complice. George Lakoff a montre que les metaphores conceptuelles structurent profondement notre pensee politique.</p>'
    '<div class="highlight-box"><p>George Lakoff : les metaphores conceptuelles ne sont pas des figures de style — elles structurent notre pensee. Appeler une loi de protection sociale une <em>charge fiscale</em> ou un <em>investissement social</em> produit des reactions politiques radicalement differentes.</p></div>'
    '<h3>Propagande, desinformation et contre-rhetorique</h3>'
    '<p class="resume-text">La <strong>propagande</strong> est une forme de communication persuasive qui cherche a influencer les attitudes et comportements d\'un grand nombre de personnes en s\'appuyant sur des techniques rhetorico-psychologiques : appel a l\'autorite, au groupe, a la peur, au patriotisme ; repetition des slogans ; simplification manichéenne (nous/eux). Jacques Ellul (<em>Propagandes</em>, 1962) distingua la propagande d\'agitation (qui mobilise pour l\'action immediate) de la propagande d\'integration (qui consolide les valeurs et l\'identite d\'un groupe).</p>'
    '<p class="resume-text">La <strong>rhetorique democratique</strong> exige la contre-rhetorique : la capacite a identifier les sophismes (ad hominem, pente glissante, faux dilemme, generalisation abusive, homme de paille), a verifier les faits et a evaluer la qualite des arguments. L\'education aux medias et a l\'information (EMI) vise a developper ces competences critiques. Le philosophe <strong>Stephen Toulmin</strong> a propose un modele d\'argumentation pratique — donnee, affirmation, justification, appui, refutation possible, qualificateur — qui permet d\'analyser et de construire des arguments valides dans des contextes quotidiens.</p>'
    '<div class="highlight-box"><p>Le modele de Toulmin : un bon argument articule une donnee, une affirmation, une justification et anticipe les refutations possibles. C\'est la base de tout raisonnement rigoureux.</p></div>'
    '<h3>Rhetorique numerique et nouveaux enjeux persuasifs</h3>'
    '<p class="resume-text">Le <strong>Web 2.0</strong> a transforme la rhetorique en multipliant les emetteurs et les formats : posts, tweets, stories, videos courtes, podcasts. La <strong>rhetorique numerique</strong> (Andrew Feenberg, James Crosswhite) etudie les nouvelles strategies persuasives adaptees aux environnements en ligne : economy d\'attention, viralite, engagement emotionnel, personnalisation algorithmique. Le clickbait, les titres sensationnalistes et les images choc exploitent les biais cognitifs (curiosite, indignation, peur) pour maximiser les clics et les partages.</p>'
    '<p class="resume-text">Les <strong>dark patterns</strong> en UX design et les techniques de neuromarketing numerique (A/B testing, eye-tracking, personnalisation predite par IA) constituent une forme de persuasion algorithmique qui echappe a la conscience du sujet. Shoshana Zuboff (<em>L\'Age du capitalisme de surveillance</em>, 2019) analyse comment les plateformes collectent les donnees comportementales pour predire et influencer les comportements d\'achat, electoraux et sociaux. Cette persuasion invisible pose des questions ethiques fondamentales sur l\'autonomie et la deliberation democratique.</p>'
    '<div class="highlight-box"><p>Shoshana Zuboff : le capitalisme de surveillance ne vend pas seulement des publicites — il vend des certitudes comportementales. La prediction du comportement est la nouvelle matiere premiere de l\'economie numerique.</p></div>'
)
pages[k]['content'] = enrich_contenu(pages[k]['content'], extra)
